INSERT IGNORE INTO `creature_text_locale` (`CreatureID`,`GroupID`,`ID`,`Locale`,`Text`) VALUES
(9916201,0,0,'zhCN','风暴嗅到了鲜血的气息。'),
(9916201,1,0,'zhCN','你快不过雷霆。'),
(9916201,2,0,'zhCN','超载！狩猎到此为止。'),
(9916201,3,0,'zhCN','风暴……消散了……'),
(9916201,4,0,'zhCN','感受骨髓中的风暴吧！'),
(164511,0,0,'zhCN','一团粗糙的红毛缠结在毛皮堆里。阿贝隆来过这里。'),
(164511,1,0,'zhCN','草地被两串脚印踩踏过，后一串紧紧咬着前一串。'),
(164511,2,0,'zhCN','一面克雷斯特黑氏族民兵圆盾，盾缘有一记重击留下的缺口。这一定是凯恩的。'),
(164511,3,0,'zhCN','泥地里干涸的脚印一路通向艾尔迪尔的地界。兄弟俩谁也没有回头。'),
(164511,4,0,'zhCN','石头上溅着血迹。有人在这里受了重伤。'),
(162700,0,0,'zhCN','又一个异端？告诉我——你犯的是什么罪？'),
(162700,1,0,'zhCN','无所谓了。恐怕牢房已经满了。你……将被处决。'),
(162700,2,0,'zhCN','圣光保佑……赐予我执掌此职的荣光。'),
(162700,3,0,'zhCN','快逃命吧！'),
(162700,5,0,'zhCN','圣光……圣光在哪里……？为何我只看见……阴影……？'),
(162703,0,0,'zhCN','有观众了！而且这次的客人是有血有肉的！'),
(162703,1,0,'zhCN','他的鲜血拓宽了我们的心智。赐予了我们力量……'),
(162703,2,0,'zhCN','最好别变成那些鬼魂之一，嗯？'),
(162703,2,1,'zhCN','来吧来吧！我们的雏崽啃够了没肉的骨头！'),
(162703,3,0,'zhCN','不！我的主人会救我。他赐予我了智慧。力量。一座王座……'),
(162703,4,0,'zhCN','什么？不！住手！我们还能谈……！'),
(162703,5,0,'zhCN','在你前方……只剩……死亡……'),
(162703,7,0,'zhCN','让雏崽们拿这家伙的骨头消遣吧！'),
(162703,8,0,'zhCN','你也是为那些低语而来的？他也召唤了你吗？'),
(162704,0,0,'zhCN','愚人。你做的每一个选择，都把你引到了我的面前。'),
(162704,1,0,'zhCN','你们的灵魂，就是打开我囚牢封印的钥匙。'),
(162704,2,0,'zhCN','你以为圣光会拯救你？它背弃了审判官们——对你也会一样。'),
(162704,5,0,'zhCN','你以为你们赢了？你们真是……天真……'),
(162704,6,0,'zhCN','煽动教会的残酷竟如此容易，我甚至怀疑没有我的推手他们也做得出来。'),
(162704,7,0,'zhCN','一颗圣光水晶出现来帮助你！'),
(162734,0,0,'zhCN','在光明之殿，一切皆是阴影……'),
(162734,0,1,'zhCN','你的罪孽是锁链、绳索、利刃……'),
(162734,0,2,'zhCN','加入我们的行列吧！'),
(162734,1,0,'zhCN','谢谢你……'),
(162734,1,1,'zhCN','不再有痛苦……不再有痛苦！够了！'),
(162736,0,0,'zhCN','在光明之殿，一切皆是阴影……'),
(162736,0,1,'zhCN','你的罪孽是锁链、绳索、利刃……'),
(162736,0,2,'zhCN','加入我们的行列吧！'),
(162736,1,0,'zhCN','我的判决……我自由了吗？'),
(162737,0,0,'zhCN','有活物！拉警报！拉警报！'),
(162737,0,1,'zhCN','鬼魂？不！他们是活人。我要啃了你的骨头！'),
(162737,0,2,'zhCN','狗头人国王没有邀请你们。你们是入侵者！'),
(162737,1,0,'zhCN','但是……！你们这些混蛋！'),
(162737,1,1,'zhCN','点一支蜡烛……为我的灵魂……'),
(162738,0,0,'zhCN','狗头人国王没有邀请你们。你们是入侵者！'),
(162738,1,0,'zhCN','点一支蜡烛……为我的灵魂……'),
(162759,0,0,'zhCN','有活物！拉警报！拉警报！'),
(162759,0,1,'zhCN','鬼魂？不！他们是活人。我要啃了你的骨头！'),
(162759,0,2,'zhCN','狗头人国王没有邀请你们。你们是入侵者！'),
(162759,1,0,'zhCN','但是……！你们这些混蛋！'),
(162759,1,1,'zhCN','点一支蜡烛……为我的灵魂……'),
(162761,0,0,'zhCN','囚徒……还是狱卒？'),
(162762,0,0,'zhCN','有活物！拉警报！拉警报！'),
(162762,0,1,'zhCN','鬼魂？不！他们是活人。我要啃了你的骨头！'),
(162762,0,2,'zhCN','狗头人国王没有邀请你们。你们是入侵者！'),
(162762,1,0,'zhCN','但是……！你们这些混蛋！'),
(162762,1,1,'zhCN','点一支蜡烛……为我的灵魂……'),
(162763,0,0,'zhCN','狗头人国王没有邀请你们。你们是入侵者！'),
(162763,1,0,'zhCN','点一支蜡烛……为我的灵魂……'),
(163813,0,0,'zhCN','有活物！拉警报！拉警报！'),
(163813,0,1,'zhCN','鬼魂？不！他们是活人。我要啃了你的骨头！'),
(163813,0,2,'zhCN','狗头人国王没有邀请你们。你们是入侵者！'),
(163813,1,0,'zhCN','但是……！你们这些混蛋！'),
(163813,1,1,'zhCN','点一支蜡烛……为我的灵魂……'),
(9916212,1,0,'zhCN','你快不过雷霆。'),
(9916212,2,0,'zhCN','超载！狩猎到此为止。'),
(9916212,0,0,'zhCN','风暴来索命了。');
INSERT IGNORE INTO `npc_text_locale` (`ID`,`Locale`,`Text0_0`) VALUES
(900001,'zhCN','架子上的毛皮小心点，它们还在鞣制。……你一脸像是杀过会反抗的东西。很好。坐下吧。'),
(900002,'zhCN','你身上是尘土味，不是城里味。很好。祖尔卡哈不跟城里猎人浪费唇舌。'),
(9360001,'zhCN','但是……我是无辜的……！$B$B<幽灵像挨鞭子一样嚎叫。他似乎被困在牢房铁栏的记忆里，无法前行。>');
